import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';

import bg1 from '../../assets/cec11.jpeg';
import bg2 from '../../assets/cec12.jpg';
import bg3 from '../../assets/cec14.jpeg';
import bg4 from '../../assets/cec15.webp';

const images = [bg1, bg2, bg3, bg4];

const Hero = () => {
    const [currentIndex, setCurrentIndex] = useState(0);

    // Automatic sliding effect (change slide every 5 seconds)
    useEffect(() => {
        const interval = setInterval(() => {
            setCurrentIndex((prevIndex) => (prevIndex + 1) % images.length);
        }, 5000);
        return () => clearInterval(interval);
    }, []);

    const prevSlide = () => {
        setCurrentIndex((prevIndex) => (prevIndex === 0 ? images.length - 1 : prevIndex - 1));
    };

    const nextSlide = () => {
        setCurrentIndex((prevIndex) => (prevIndex + 1) % images.length);
    };

    return (
        <section id="home" className="relative group h-[450px] w-full overflow-hidden bg-slate-900 md:h-[600px]">
            {/* Slider track */}
            <div 
                className="flex h-full w-full transition-transform duration-1000 ease-in-out"
                style={{ transform: `translateX(-${currentIndex * 100}%)` }}
            >
                {images.map((img, index) => (
                    <div
                        key={index}
                        className="h-full min-w-full bg-cover bg-center"
                        style={{ backgroundImage: `url(${img})` }}
                    ></div>
                ))}
            </div>

            {/* Manual Controls (Left & Right Arrows) */}
            <button
                onClick={prevSlide}
                aria-label="Previous image"
                className="absolute left-4 top-1/2 -translate-y-1/2 rounded-full bg-black/20 p-2 text-white/80 opacity-0 backdrop-blur-sm transition-all duration-300 hover:bg-black/50 hover:text-white hover:scale-110 group-hover:opacity-100 md:left-8 md:p-3"
            >
                <ChevronLeft size={36} />
            </button>
            <button
                onClick={nextSlide}
                aria-label="Next image"
                className="absolute right-4 top-1/2 -translate-y-1/2 rounded-full bg-black/20 p-2 text-white/80 opacity-0 backdrop-blur-sm transition-all duration-300 hover:bg-black/50 hover:text-white hover:scale-110 group-hover:opacity-100 md:right-8 md:p-3"
            >
                <ChevronRight size={36} />
            </button>

            {/* Indicator Dots */}
            <div className="absolute bottom-6 left-1/2 flex -translate-x-1/2 gap-3">
                {images.map((_, index) => (
                    <button
                        key={index}
                        onClick={() => setCurrentIndex(index)}
                        aria-label={`Go to slide ${index + 1}`}
                        className={`h-[10px] w-[10px] rounded-full transition-all duration-300 ${
                            currentIndex === index ? 'bg-white scale-125 w-[14px]' : 'bg-white/40 hover:bg-white/80'
                        }`}
                    ></button>
                ))}
            </div>
        </section>
    );
};

export default Hero;
